CREATE TABLE hospitalization_orders (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, hospitalization_id VARCHAR(100) NOT NULL REFERENCES hospitalizations(id), order_type VARCHAR(50) NOT NULL, instructions TEXT NOT NULL, frequency VARCHAR(100), priority VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancelled_by VARCHAR(100), cancel_reason TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE hospitalization_order_schedules (id VARCHAR(100) PRIMARY KEY, tenant_id UUID NOT NULL, order_id VARCHAR(100) NOT NULL REFERENCES hospitalization_orders(id), scheduled_for TIMESTAMPTZ NOT NULL, applied_at TIMESTAMPTZ, applied_by_user_id VARCHAR(100), skipped_at TIMESTAMPTZ, skipped_by_user_id VARCHAR(100), skip_reason TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX hospitalization_orders_tenant_hospitalization_status_idx ON hospitalization_orders(tenant_id,hospitalization_id,status); CREATE INDEX hospitalization_order_schedules_tenant_order_time_idx ON hospitalization_order_schedules(tenant_id,order_id,scheduled_for);
ALTER TABLE hospitalization_orders ENABLE ROW LEVEL SECURITY; ALTER TABLE hospitalization_orders FORCE ROW LEVEL SECURITY; ALTER TABLE hospitalization_order_schedules ENABLE ROW LEVEL SECURITY; ALTER TABLE hospitalization_order_schedules FORCE ROW LEVEL SECURITY;
CREATE POLICY hospitalization_orders_tenant ON hospitalization_orders USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY hospitalization_order_schedules_tenant ON hospitalization_order_schedules USING (tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK (tenant_id=current_setting('app.tenant_id',true)::uuid);
